test_patch:
diff --git a/mysql-test/r/server_offline_debug.result b/mysql-test/r/server_offline_debug.result
index 63b86102c2d4..77ad1ca60d9a 100644
--- a/mysql-test/r/server_offline_debug.result
+++ b/mysql-test/r/server_offline_debug.result
@@ -13,3 +13,22 @@ offline_mode	ON
 SET DEBUG_SYNC='RESET';
 # Restoring the original values.
 SET @@global.offline_mode = @global_saved_tmp;
+#
+# Bug #29849046: ASSERT AT SQL_PARSE.CC:6421 IF NON-PRIVILEGED USER
+#   TRIES ENABLING OFFLINE_MODE
+SET @global_saved_tmp =  @@global.offline_mode;
+CREATE USER u1@localhost;
+GRANT ALL PRIVILEGES ON *.* to u1@localhost;
+REVOKE CONNECTION_ADMIN, SUPER ON *.* FROM u1@localhost;
+Warnings:
+Warning	1287	The SUPER privilege identifier is deprecated
+# in connection con_u1
+# test: must not assert
+set global offline_mode=on;
+# Should have killed itself
+SELECT 1 FROM DUAL;
+ERROR HY000: MySQL server has gone away
+in connection default
+SET @@global.offline_mode = @global_saved_tmp;
+DROP USER u1@localhost;
+# End of 8.0 tests
diff --git a/mysql-test/t/server_offline_debug.test b/mysql-test/t/server_offline_debug.test
index 6e2369e0c252..565218bf473b 100644
--- a/mysql-test/t/server_offline_debug.test
+++ b/mysql-test/t/server_offline_debug.test
@@ -26,3 +26,38 @@ SET DEBUG_SYNC='materialize_session_variable_array_THD_locked SIGNAL lock_thd_da
 SET DEBUG_SYNC='RESET';
 --echo # Restoring the original values.
 SET @@global.offline_mode = @global_saved_tmp;
+
+
+--echo #
+--echo # Bug #29849046: ASSERT AT SQL_PARSE.CC:6421 IF NON-PRIVILEGED USER
+--echo #   TRIES ENABLING OFFLINE_MODE
+
+# Save the initial number of concurrent sessions
+--source include/count_sessions.inc
+# Save the global value to be used to restore the original value.
+SET @global_saved_tmp =  @@global.offline_mode;
+
+CREATE USER u1@localhost;
+GRANT ALL PRIVILEGES ON *.* to u1@localhost;
+REVOKE CONNECTION_ADMIN, SUPER ON *.* FROM u1@localhost;
+
+connect(con_u1,localhost,u1,,test);
+--echo # in connection con_u1
+connection con_u1;
+
+--echo # test: must not assert
+set global offline_mode=on;
+
+--echo # Should have killed itself
+--error CR_SERVER_GONE_ERROR
+SELECT 1 FROM DUAL;
+
+--echo in connection default
+connection default;
+disconnect con_u1;
+SET @@global.offline_mode = @global_saved_tmp;
+# Wait till all disconnects are completed
+--source include/wait_until_count_sessions.inc
+DROP USER u1@localhost;
+
+--echo # End of 8.0 tests
